// Veltria Agenda Completo · protótipo "balcão da recepção" para salão com equipe.
// À esquerda a fila (quem chegou, quem está na cadeira, quem vai pagar), no meio a grade de cada profissional,
// à direita a comanda aberta com serviços, produtos e pacote. Mais: clientes, pacotes, produtos, comissões,
// caixa do dia, lembretes automáticos, relatórios, equipe, ajustes e assistente. Dados de exemplo (?novo recomeça).

const CHAVE = 'veltria-agenda-completo-v1';
const R$ = (v) => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const es = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const sa = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const nv = (v) => Number(String(v ?? '').replace(/\./g, '').replace(',', '.')) || 0;
const uid = () => `c${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`;
const hm = (h) => `${String(Math.floor(h)).padStart(2, '0')}:${String(Math.round((h % 1) * 60)).padStart(2, '0')}`;
const $ = (s) => document.querySelector(s);
const PX = 52, ABRE = 8, FECHA = 20;
const agoraH = () => { const d = new Date(); return d.getHours() + d.getMinutes() / 60; };

function semente() {
  const pros = [['p1', 'Rose', 'Cabelo e coloração', '#425c70', 45], ['p2', 'Kátia', 'Cabelo e escova', '#94624f', 40], ['p3', 'Amanda', 'Unhas', '#6f8a82', 50], ['p4', 'Júlio', 'Barba e corte masculino', '#7b6f8f', 45]].map(([id, nome, area, cor, com]) => ({ id, nome, area, cor, com, comProd: 10 }));
  const servs = [['corte-f', 'Corte feminino', 60, 90], ['escova', 'Escova', 45, 55], ['color', 'Coloração', 120, 220], ['mechas', 'Mechas', 180, 380], ['hidrat', 'Hidratação', 45, 80], ['mao', 'Manicure', 45, 38], ['pe', 'Pedicure', 50, 42], ['gel', 'Unha em gel', 120, 150], ['corte-m', 'Corte masculino', 40, 55], ['barba', 'Barba', 30, 40]].map(([id, nome, min, preco]) => ({ id, nome, min, preco }));
  const prods = [['Shampoo Kérastase 250 ml', 189, 112, 6, 3], ['Máscara Wella 150 ml', 129, 74, 2, 3], ['Óleo reparador', 98, 51, 9, 4], ['Esmalte em gel (un.)', 32, 14, 24, 10], ['Pomada modeladora', 65, 31, 1, 4]].map(([nome, preco, custo, qtd, min]) => ({ id: uid(), nome, preco, custo, qtd, min }));
  const clientes = [['Helena Duarte', '31997650001', '14/11', 'Coloração 6.1, sem amônia'], ['Marcela Viana', '31997650002', '03/12', 'Cabelo fino, não gosta de secador quente'], ['Joana Pires', '31997650003', '22/10', 'Alérgica a acetona'], ['Rafael Gomes', '31997650004', '09/01', 'Degradê baixo, máquina 1'], ['Larissa Campos', '31997650005', '27/10', 'Mechas finas, tonalizante pérola'], ['Beatriz Alves', '31997650006', '15/02', ''], ['Cláudia Neves', '31997650007', '30/10', 'Prefere a Kátia'], ['Pedro Souza', '31997650008', '05/05', ''], ['Sônia Ramos', '31997650009', '18/03', 'Pacote de escova'], ['Tatiane Mello', '31997650010', '11/08', '']].map(([nome, tel, niver, obs]) => ({ id: uid(), nome, tel, niver, obs, visitas: 3 + nome.length % 9, gasto: 400 + nome.length * 83, ultima: -(6 + (nome.length * 13) % 84), hist: [] }));
  const cl = (n) => clientes.find((c) => c.nome.startsWith(n)).id;
  const A = (pro, ini, cli, serv, st) => ({ id: uid(), pro, ini, cli: cl(cli), st, itens: [{ tipo: 's', ref: serv, pro }], pago: null });
  const ags = [A('p1', 8.5, 'Helena', 'color', 'pago'), A('p1', 11, 'Larissa', 'mechas', 'atendendo'), A('p1', 15, 'Marcela', 'corte-f', 'agendado'), A('p1', 16.5, 'Beatriz', 'hidrat', 'agendado'),
    A('p2', 9, 'Sônia', 'escova', 'pago'), A('p2', 10.5, 'Cláudia', 'corte-f', 'pagar'), A('p2', 13, 'Tatiane', 'escova', 'chegou'), A('p2', 14, 'Beatriz', 'corte-f', 'agendado'), A('p2', 17, 'Sônia', 'escova', 'agendado'),
    A('p3', 9, 'Joana', 'mao', 'pago'), A('p3', 10, 'Joana', 'pe', 'pago'), A('p3', 13, 'Marcela', 'gel', 'chegou'), A('p3', 16, 'Tatiane', 'mao', 'agendado'),
    A('p4', 9.5, 'Rafael', 'corte-m', 'faltou'), A('p4', 12.5, 'Pedro', 'corte-m', 'atendendo'), A('p4', 13.5, 'Pedro', 'barba', 'agendado'), A('p4', 15, 'Rafael', 'corte-m', 'agendado')];
  [['p1', 10, 'Larissa', 'hidrat'], ['p2', 9.5, 'Marcela', 'escova'], ['p3', 14, 'Helena', 'mao']].forEach(([p, h, c, sv]) => ags.push({ ...A(p, h, c, sv, 'agendado'), dia: 1 })); // amanhã: para os lembretes de confirmação
  ags.find((a) => a.st === 'pago' && a.pro === 'p1').pago = { forma: 'Cartão', total: 220 }; ags.filter((a) => a.st === 'pago' && !a.pago).forEach((a) => { a.pago = { forma: 'PIX', total: servs.find((s) => s.id === a.itens[0].ref).preco }; });
  const pacotes = [{ id: uid(), cli: cl('Sônia'), nome: '10 escovas', total: 10, usadas: 7, valor: 450 }, { id: uid(), cli: cl('Joana'), nome: '4 manicures + pés', total: 4, usadas: 1, valor: 280 }];
  const bloqueios = [{ id: uid(), pro: 'p3', dia: 0, ini: 12, fim: 13, motivo: 'Almoço' }, { id: uid(), pro: 'p4', dia: 1, ini: 8, fim: 20, motivo: 'Folga' }];
  const espera = [{ id: uid(), cli: cl('Beatriz'), serv: 'escova', pro: 'p2', obs: 'Qualquer horário depois das 14h' }, { id: uid(), cli: cl('Pedro'), serv: 'barba', pro: '', obs: '' }];
  // funções de 10/2026 (2ª leva): pedidos de horário, vales, fidelidade, despesas, metas, escala, promoções, consumo, alertas
  pros.forEach((p, i) => { p.meta = [900, 700, 500, 450][i]; p.folga = [[0], [0, 1], [0], [0, 3]][i]; });
  const P = (n) => prods.find((p) => p.nome.startsWith(n)).id;
  servs.find((s) => s.id === 'hidrat').consumo = [{ prod: P('Máscara'), q: 0.2 }]; servs.find((s) => s.id === 'gel').consumo = [{ prod: P('Esmalte'), q: 1 }];
  clientes.forEach((c) => { c.pontos = Math.floor(c.gasto); });
  clientes.find((c) => c.nome.startsWith('Joana')).alerta = 'Alérgica a acetona: usar removedor sem acetona';
  clientes.find((c) => c.nome.startsWith('Helena')).tecnica = [{ em: new Date(Date.now() - 40 * 864e5).toISOString(), serv: 'Coloração', txt: 'Igora 6.1 + ox 20 vol, 35 min de pausa' }];
  clientes.find((c) => c.nome.startsWith('Rafael')).faltas = 1;
  const online = [{ id: uid(), nome: 'Fernanda Lopes', tel: '31997650011', serv: 'escova', pro: 'p2', dia: 1, ini: 16, canal: 'Instagram', obs: 'Primeira vez no salão' }, { id: uid(), nome: 'Marcela Viana', tel: '31997650002', serv: 'mao', pro: 'p3', dia: 2, ini: 10, canal: 'WhatsApp', obs: '' }];
  const vales = [{ cod: 'PRES-4821', valor: 150, saldo: 150, para: 'Cláudia Reis', de: 'Marcos', em: new Date(Date.now() - 6 * 864e5).toISOString() }];
  const despesas = [{ id: uid(), desc: 'Aluguel (parte do dia)', v: 120, dia: 0, tipo: 'Fixa' }, { id: uid(), desc: 'Energia e água (parte do dia)', v: 38, dia: 0, tipo: 'Fixa' }, { id: uid(), desc: 'Café e água para clientes', v: 22, dia: 0, tipo: 'Variável' }];
  const promos = [{ id: uid(), serv: 'escova', dow: 2, pct: 20 }, { id: uid(), serv: 'mao', dow: 3, pct: 15 }];
  return { salao: 'Salão Ateliê Bela Vista', pros, servs, prods, clientes, ags, pacotes, bloqueios, espera, online, vales, despesas, promos, vendas: [], cancelados: [], fid: { ligado: true, porReal: 1, pts: 100, vale: 10 }, entradas: [], fechamentos: [], retornoDias: 45, caixaIni: 200, sangrias: [], lembretes: { confirmar: true, aniversario: true, retorno: true }, plano: 'basico', conversa: [] };
}
const lista = (k) => (db[k] ||= []); // dados de antes destas funções não têm as listas novas
let db = (() => { if (new URLSearchParams(location.search).has('novo')) localStorage.removeItem(CHAVE); try { return JSON.parse(localStorage.getItem(CHAVE)) || semente(); } catch { return semente(); } })();
window.veltriaDados = () => db; // modo conta: começar do zero e resumo para a IA
const guarda = () => { try { localStorage.setItem(CHAVE, JSON.stringify(db)); } catch { aviso('Sem espaço no navegador.'); } };
// profissional, serviço ou produto apagado: um vazio no lugar, para a agenda não quebrar
const pro = (id) => db.pros.find((p) => p.id === id) || { id: '', nome: '—', area: '', cor: '#8a8f9c', com: 0, comProd: 0 };
const sv = (id) => db.servs.find((s) => s.id === id) || { id: '', nome: '—', min: 30, preco: 0 };
const prod = (id) => db.prods.find((p) => p.id === id) || { id: '', nome: '—', preco: 0, custo: 0, qtd: 0, min: 0 };
const cli = (id) => db.clientes.find((c) => c.id === id) || { nome: '—', tel: '' };
// nome escrito à mão num campo (campos livres): se ainda não existe, vira cadastro novo
const cliDe = (v) => { v = String(v || '').trim(); if (!v || db.clientes.some((c) => c.id === v)) return v; const ja = db.clientes.find((c) => c.nome.toLowerCase() === v.toLowerCase()); if (ja) return ja.id; const n = { id: uid(), nome: v, tel: '', niver: '', obs: '', visitas: 0, gasto: 0, pontos: 0, ultima: 0, hist: [] }; db.clientes.push(n); return n.id; };
const proDe = (v) => { v = String(v || '').trim(); if (!v || db.pros.some((x) => x.id === v)) return v; const ja = db.pros.find((x) => x.nome.toLowerCase() === v.toLowerCase()); if (ja) return ja.id; const n = { id: uid(), nome: v, area: '', cor: '#8a8f9c', com: 40, comProd: 10, meta: 0, folga: [] }; db.pros.push(n); return n.id; };
// atendimentos de hoje (dia 0); "dia" ausente vale hoje (dados de antes desta mudança)
const agsHoje = () => db.ags.filter((a) => (a.dia || 0) === 0);
const nomeDia = (d) => (d === 0 ? 'Hoje' : d === 1 ? 'Amanhã' : (() => { const x = new Date(); x.setDate(x.getDate() + d); return x.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' }); })());
const ag = (id) => db.ags.find((a) => a.id === id);
const minutos = (a) => a.itens.filter((i) => i.tipo === 's').reduce((s, i) => s + sv(i.ref).min, 0) || 30;
const valorItem = (i) => (i.tipo === 's' ? (i.pacote ? 0 : sv(i.ref).preco) : prod(i.ref).preco * (i.qtd || 1));
const totalAg = (a) => a.itens.reduce((s, i) => s + valorItem(i), 0);
const ST = { agendado: ['agendada', ''], chegou: ['chegou', 'at'], atendendo: ['na cadeira', 'az'], pagar: ['vai pagar', 'ru'], pago: ['pago', 'ok'], faltou: ['faltou', 'ru'] };
let sel = null;

/** Profissional ocupado ou bloqueado nesse horário? Devolve a frase do aviso ou ''. */
function conflito(p, dia, ini, horas, ignora = '') {
  if (ini < ABRE || ini + horas > FECHA) return `Fora do horário do salão (${ABRE}h às ${FECHA}h).`;
  if ((pro(p).folga || []).includes(dow(dia))) return `${pro(p).nome} não trabalha ${DOW[dow(dia)]} (escala em Equipe).`;
  const b = lista('bloqueios').find((x) => x.pro === p && x.dia === dia && ini < x.fim && ini + horas > x.ini); if (b) return `${pro(p).nome} está com o horário bloqueado (${b.motivo}, ${hm(b.ini)}–${hm(b.fim)}).`;
  return db.ags.some((a) => a.id !== ignora && a.pro === p && (a.dia || 0) === dia && a.st !== 'faltou' && ini < a.ini + minutos(a) / 60 && ini + horas > a.ini) ? `${pro(p).nome} já tem alguém nesse horário.` : '';
}
function aviso(t) { const a = document.createElement('div'); a.className = 'aviso'; a.textContent = t; $('#avisos').append(a); setTimeout(() => a.remove(), 3300); }
function dialogo(html, liga) {
  const v = document.createElement('div'); v.className = 'sombra'; v.innerHTML = `<div class="dialogo" role="dialog" aria-modal="true">${html}</div>`;
  const ant = document.activeElement; document.body.append(v);
  const fecha = () => { v.remove(); ant?.focus?.(); };
  v.addEventListener('click', (e) => { if (e.target === v || e.target.closest('[data-sair]')) fecha(); });
  v.addEventListener('keydown', (e) => { if (e.key === 'Escape') fecha(); });
  setTimeout(() => (v.querySelector('input, select') || v.querySelector('button'))?.focus(), 30);
  liga?.(v.querySelector('.dialogo'), fecha);
}
function pergunta(t, campos, ok, fn) { dialogo(`<h2>${t}</h2><form>${campos}<div class="pe"><button type="button" class="bt" data-sair>Cancelar</button><button class="bt az">${ok}</button></div></form>`, (d, fecha) => d.querySelector('form').addEventListener('submit', (e) => { e.preventDefault(); if (fn(new FormData(e.target)) !== false) { guarda(); fecha(); tela(); } })); }

// ------------------------------------------------------------------ seções
const SECOES = [['balcao', 'Balcão'], ['online', 'Pedidos de horário'], ['espera', 'Lista de espera'], ['clientes', 'Clientes'], ['retorno', 'Chamar de volta'], ['pacotes', 'Pacotes'], ['fidelidade', 'Fidelidade e vales'], ['produtos', 'Produtos'], ['comissoes', 'Comissões'], ['caixa', 'Caixa do dia'], ['despesas', 'Despesas e metas'], ['lembretes', 'Lembretes'], ['relatorios', 'Relatórios'], ['equipe', 'Equipe'], ['ajustes', 'Ajustes']];
function proximos() {
  const l = db.ags.filter((a) => (a.dia || 0) > 0 && a.st !== 'faltou').sort((a, b) => a.dia - b.dia || a.ini - b.ini);
  if (!l.length) return '';
  return `<section class="caixa-b" style="margin-top:16px"><h2>Próximos dias (${l.length})</h2>${l.slice(0, 40).map((a) => `<p style="margin:6px 0"><b>${es(nomeDia(a.dia))} · ${hm(a.ini)}</b> · ${es(cli(a.cli).nome)} · ${es(a.itens.filter((i) => i.tipo === 's').map((i) => sv(i.ref).nome).join(' + '))} · ${es(pro(a.pro).nome)}</p>`).join('')}</section>`;
}
const S = {
  balcao() {
    const hoje = agsHoje(), grupo = (st) => hoje.filter((a) => st.includes(a.st)), hA = agoraH(), prox = hoje.filter((a) => a.st === 'agendado' && a.ini >= hA - 0.25 && a.ini <= hA + 1);
    const cart = (a) => `<button type="button" class="cartela" data-sel="${a.id}" aria-pressed="${a.id === sel}" style="--c:${pro(a.pro).cor}"><b>${es(cli(a.cli).nome)}${cli(a.cli).alerta ? ' <span class="alerta-c" title="${es(cli(a.cli).alerta)}">atenção</span>' : ''}</b><small>${hm(a.ini)} · ${es(a.itens.filter((i) => i.tipo === 's').map((i) => sv(i.ref).nome).join(' + '))} · ${es(pro(a.pro).nome)}</small></button>`;
    const fila = `<section class="caixa-b fila"><h2>Fila do balcão</h2>${[['Chegaram, esperando', ['chegou']], ['Na cadeira', ['atendendo']], ['Para pagar', ['pagar']], ['Próximos 60 minutos', null]].map(([n, st]) => { const l = st ? grupo(st) : prox; return `<div class="etapa"><small>${n} (${l.length})</small>${l.map(cart).join('') || '<p class="vazio" style="margin:0">ninguém</p>'}</div>`; }).join('')}</section>`;
    const grade = `<section class="caixa-b grade-p" style="--n:${db.pros.length}"><h2>Hoje por profissional <span class="acoes"><button type="button" class="bt p" data-a="achar">Achar horário</button><button type="button" class="bt p" data-a="avulsa">Venda no balcão</button><button type="button" class="bt p" data-a="bloquear">Bloquear horário</button><button type="button" class="bt p az" data-a="novo-ag">+ Agendar</button></span></h2><div class="cab-p"><div></div>${db.pros.map((p) => `<div style="--c:${p.cor}">${es(p.nome)}<small>${es(p.area)}</small></div>`).join('')}</div>
      <div class="corpo-p"><div class="horas">${Array.from({ length: FECHA - ABRE }, (_, i) => `<div>${ABRE + i}h</div>`).join('')}</div>${db.pros.map((p) => `<div class="col" data-col="${p.id}" style="height:${(FECHA - ABRE) * PX}px" title="Clique num horário vazio para agendar">${lista('bloqueios').filter((b) => b.pro === p.id && b.dia === 0).map((b) => `<button type="button" class="bloco bloqueio" data-a="tira-bloqueio" data-id="${b.id}" title="Tirar o bloqueio" style="top:${(b.ini - ABRE) * PX}px;height:${Math.max(24, (b.fim - b.ini) * PX - 3)}px"><b>${es(b.motivo)}</b>${hm(b.ini)}–${hm(b.fim)}</button>`).join('')}${hoje.filter((a) => a.pro === p.id).map((a) => `<button type="button" class="bloco ${a.st}" data-sel="${a.id}" aria-pressed="${a.id === sel}" style="--c:${p.cor};top:${(a.ini - ABRE) * PX}px;height:${Math.max(24, minutos(a) / 60 * PX - 3)}px"><b>${hm(a.ini)} ${es(cli(a.cli).nome.split(' ')[0])}</b>${es(a.itens.filter((i) => i.tipo === 's').map((i) => sv(i.ref).nome).join(' + '))}<br>${ST[a.st][0]}</button>`).join('')}</div>`).join('')}
      ${hA > ABRE && hA < FECHA ? `<div class="agora" style="top:${(hA - ABRE) * PX}px;left:46px"></div>` : ''}</div></section>`;
    return `<div class="topo-s"><div><h1>Balcão</h1><p>${grupo(['chegou']).length} esperando · ${grupo(['atendendo']).length} na cadeira · ${grupo(['pagar']).length} para pagar · ${R$(hoje.filter((a) => a.pago).reduce((s, a) => s + a.pago.total, 0))} recebidos hoje</p></div></div>
      <div class="balcao">${fila}${grade}${comanda()}</div>${proximos()}`;
  },
  espera() {
    const l = lista('espera');
    return `<div class="topo-s"><div><h1>Lista de espera</h1><p>Quem quer horário e não achou. Quando alguém falta ou desmarca, o balcão sugere quem chamar para o encaixe.</p></div><button class="bt az" data-a="nova-espera">+ Na lista</button></div>
      <div class="caixa-b tab"><table><thead><tr><th>Cliente</th><th>Serviço</th><th>Com</th><th>Observação</th><th></th></tr></thead><tbody>${l.map((x) => `<tr><td><b>${es(cli(x.cli).nome)}</b></td><td>${es(sv(x.serv).nome)}</td><td>${es(x.pro ? pro(x.pro).nome : 'qualquer profissional')}</td><td>${es(x.obs) || '<span class="vazio">—</span>'}</td><td><div class="acoes">${cli(x.cli).tel ? `<a class="bt p" target="_blank" rel="noopener" href="https://wa.me/55${String(cli(x.cli).tel).replace(/\D/g, '')}?text=${encodeURIComponent(`Oi, ${cli(x.cli).nome.split(' ')[0]}! Abriu um horário de ${sv(x.serv).nome} aqui no ${db.salao}. Quer encaixar?`)}">Chamar</a>` : ''}<button class="bt p" data-a="sai-espera" data-id="${x.id}">Tirar</button></div></td></tr>`).join('') || '<tr><td colspan="5" class="vazio">Ninguém esperando.</td></tr>'}</tbody></table></div>`;
  },
  retorno() {
    const dias = db.retornoDias || 45, l = db.clientes.filter((c) => Number.isFinite(c.ultima) && -c.ultima >= dias).sort((a, b) => a.ultima - b.ultima);
    return `<div class="topo-s"><div><h1>Chamar de volta</h1><p>Clientes sem vir há ${dias} dias ou mais. O botão abre o seu WhatsApp com a mensagem pronta; quem envia é você.</p></div><span class="acoes"><label class="cmp" style="margin:0">Dias sem vir<input data-aj="retornoDias" type="number" min="7" max="365" value="${dias}" style="width:80px"></label><button class="bt az" data-a="nova-cli">+ Cliente</button></span></div>
      <div class="caixa-b tab"><table><thead><tr><th>Cliente</th><th class="d">Última visita</th><th class="d">Visitas</th><th class="d">Gastou</th><th></th></tr></thead><tbody>${l.map((c) => `<tr><td><b>${es(c.nome)}</b>${c.obs ? `<br><small class="vazio">${es(c.obs)}</small>` : ''}</td><td class="d">há ${-c.ultima} dias</td><td class="d">${c.visitas}</td><td class="d">${R$(c.gasto)}</td><td style="white-space:nowrap"><button class="bt p" data-a="novo-ag" data-c="${c.id}">Agendar</button> ${c.tel ? `<a class="bt p" target="_blank" rel="noopener" href="https://wa.me/55${String(c.tel).replace(/\D/g, '')}?text=${encodeURIComponent(`Oi, ${c.nome.split(' ')[0]}! Sentimos sua falta aqui no ${db.salao}. Quer marcar um horário esta semana?`)}">WhatsApp</a>` : ''}</td></tr>`).join('') || '<tr><td colspan="5" class="vazio">Ninguém sumido. Todas vieram nos últimos dias.</td></tr>'}</tbody></table></div>`;
  },
  clientes() {
    const mesAtual = new Date().getMonth() + 1, niver = db.clientes.filter((c) => Number(c.niver.split('/')[1]) === mesAtual);
    return `<div class="topo-s"><div><h1>Clientes</h1><p>${db.clientes.length} clientes · ${niver.length} fazem aniversário este mês.</p></div><button class="bt az" data-a="nova-cli">+ Cliente</button></div>
      <div class="caixa-b tab"><table><thead><tr><th>Cliente</th><th>Anotações da ficha</th><th>Aniversário</th><th class="d">Visitas</th><th class="d">Gastou</th><th></th></tr></thead><tbody>${db.clientes.map((c) => `<tr><td><b>${es(c.nome)}</b>${c.alerta ? ' <span class="alerta-c" title="${es(c.alerta)}">atenção</span>' : ''}${faltas(c.id) ? `<br><small class="vazio">${faltas(c.id)} falta(s)</small>` : ''}${db.fid?.ligado ? `<br><small class="vazio">${c.pontos || 0} pontos</small>` : ''}</td><td>${es(c.obs) || '<span class="vazio">—</span>'}</td><td>${es(c.niver)} ${Number(c.niver.split('/')[1]) === mesAtual ? '<span class="etq at">este mês</span>' : ''}</td><td class="d">${c.visitas}</td><td class="d">${R$(c.gasto)}</td><td><div class="acoes"><button class="bt p" data-a="ficha" data-id="${c.id}">Ficha</button><button class="bt p" data-a="tecnica" data-id="${c.id}">Ficha técnica</button><a class="bt p" target="_blank" rel="noopener" href="https://wa.me/55${c.tel}?text=${encodeURIComponent(`Oi, ${c.nome.split(' ')[0]}! Aqui é do ${db.salao}.`)}">WhatsApp</a></div></td></tr>`).join('')}</tbody></table></div>`;
  },
  pacotes() {
    return `<div class="topo-s"><div><h1>Pacotes</h1><p>Sessões vendidas adiantadas. Na comanda, use "Usar pacote" e a sessão sai sem cobrar.</p></div><button class="bt az" data-a="novo-pacote">+ Vender pacote</button></div>
      <div class="caixa-b tab"><table><thead><tr><th>Cliente</th><th>Pacote</th><th>Sessões</th><th class="d">Pago</th><th></th></tr></thead><tbody>${db.pacotes.map((p) => `<tr><td><b>${es(cli(p.cli).nome)}</b></td><td>${es(p.nome)}</td><td><div class="sessoes" aria-label="${p.usadas} de ${p.total} usadas">${Array.from({ length: p.total }, (_, i) => `<i class="${i < p.usadas ? 'u' : ''}"></i>`).join('')}</div><small class="vazio">${p.total - p.usadas} restante(s)</small></td><td class="d">${R$(p.valor)}</td><td>${p.total - p.usadas <= 2 ? '<span class="etq at">ofereça renovar</span>' : ''}</td></tr>`).join('')}</tbody></table></div>`;
  },
  produtos() {
    const baixo = db.prods.filter((p) => p.qtd < p.min);
    return `<div class="topo-s"><div><h1>Produtos de revenda</h1><p>${baixo.length} abaixo do mínimo. Vendidos na comanda, com comissão para quem indicou.</p></div><button class="bt az" data-a="novo-prod">+ Produto</button></div>
      <div class="caixa-b tab"><table><thead><tr><th>Produto</th><th class="d">Estoque</th><th class="d">Mínimo</th><th class="d">Custo</th><th class="d">Venda</th><th class="d">Margem</th><th></th></tr></thead><tbody>${db.prods.map((p) => `<tr><td>${es(p.nome)}</td><td class="d">${p.qtd < p.min ? `<span class="etq ru">${p.qtd}</span>` : p.qtd}</td><td class="d">${p.min}</td><td class="d">${R$(p.custo)}</td><td class="d">${R$(p.preco)}</td><td class="d">${Math.round((p.preco - p.custo) / p.preco * 100)}%</td><td><button class="bt p" data-a="entrada" data-id="${p.id}">Entrada</button></td></tr>`).join('')}</tbody></table></div>${lista('entradas').length ? `<section class="caixa-b" style="margin-top:16px"><h2>Entradas de estoque</h2><table><tbody>${db.entradas.slice(-12).reverse().map((x) => `<tr><td>${new Date(x.em).toLocaleDateString('pt-BR')}</td><td>${es(prod(x.prod).nome)}</td><td class="d">+${x.q}</td><td class="d">${R$(x.custo)} cada</td></tr>`).join('')}</tbody></table></section>` : ''}`;
  },
  comissoes() {
    const l = db.pros.map((p) => { const its = agsHoje().filter((a) => a.pago).flatMap((a) => a.itens.filter((i) => i.pro === p.id)); const s = its.filter((i) => i.tipo === 's').reduce((t, i) => t + valorItem(i), 0), pr = its.filter((i) => i.tipo === 'p').reduce((t, i) => t + valorItem(i), 0); const gor = agsHoje().filter((a) => a.pago?.gorjeta && a.pro === p.id).reduce((t, a) => t + a.pago.gorjeta, 0); return { p, s, pr, gor, c: s * p.com / 100 + pr * p.comProd / 100 + gor }; });
    return `<div class="topo-s"><div><h1>Comissões de hoje</h1><p>Sobre o que já foi pago. Serviço e produto têm porcentagens separadas.</p></div><button class="bt" data-a="vale">Lançar vale</button></div>
      <div class="caixa-b tab"><table><thead><tr><th>Profissional</th><th class="d">Serviços</th><th class="d">% serv.</th><th class="d">Produtos</th><th class="d">% prod.</th><th class="d">Gorjetas</th><th class="d">A receber</th></tr></thead><tbody>${l.map((x) => `<tr><td><b>${es(x.p.nome)}</b></td><td class="d">${R$(x.s)}</td><td class="d"><input data-com="${x.p.id}" value="${x.p.com}" style="width:46px;text-align:right" aria-label="Comissão de serviço de ${es(x.p.nome)}">%</td><td class="d">${R$(x.pr)}</td><td class="d">${x.p.comProd}%</td><td class="d">${x.gor ? R$(x.gor) : ''}</td><td class="d"><b>${R$(x.c)}</b></td></tr>`).join('')}</tbody></table></div>
      <div class="cols" style="margin-top:16px"><section class="caixa-b c8"><h2>Quanto cada um gerou hoje</h2><div class="barras">${l.map((x) => `<div class="l"><span>${es(x.p.nome)}</span><span class="t"><i style="--c:${x.p.cor};width:${Math.round((x.s + x.pr) / (Math.max(...l.map((y) => y.s + y.pr)) || 1) * 100)}%"></i></span><span class="d">${R$(x.s + x.pr)}</span></div>`).join('')}</div></section>
      <section class="caixa-b c4 total-com"><h2>Total de comissões hoje</h2><p class="num">${R$(l.reduce((t, x) => t + x.c, 0))}</p><p class="rot">somando a equipe toda, sobre o que já foi pago</p></section></div>`;
  },
  caixa() {
    const pagos = agsHoje().filter((a) => a.pago), porForma = {}; pagos.forEach((a) => (a.pago.partes || [{ forma: a.pago.forma, v: a.pago.total }]).forEach((x) => { porForma[x.forma] = (porForma[x.forma] || 0) + x.v; }));
    lista('vendas').filter((v) => !v.dia).forEach((v) => { porForma[v.forma] = (porForma[v.forma] || 0) + v.total; });
    const din = (porForma.Dinheiro || 0) + db.caixaIni - db.sangrias.reduce((s, x) => s + x.v, 0);
    return `<div class="topo-s"><div><h1>Caixa do dia</h1><p>Abriu com ${R$(db.caixaIni)} em dinheiro.</p></div><div class="acoes"><button class="bt" data-a="sangria">Sangria</button><button class="bt az" data-a="fechar-caixa">Fechar o caixa</button></div></div>
      <div class="cols">${['PIX', 'Cartão', 'Dinheiro'].map((f) => `<div class="caixa-b c4"><span class="rot">${f}</span><p class="num">${R$(porForma[f] || 0)}</p></div>`).join('')}
      <section class="caixa-b c6"><h2>Na gaveta agora</h2><p class="num">${R$(din)}</p><p class="rot">abertura + dinheiro recebido − sangrias</p></section>
      <section class="caixa-b c6"><h2>Recebimentos</h2><table><tbody>${pagos.map((a) => `<tr><td>${hm(a.ini)} ${es(cli(a.cli).nome)}</td><td>${es(a.pago.partes ? a.pago.partes.map((x) => `${x.forma} ${R$(x.v)}`).join(' + ') : a.pago.forma)}</td><td class="d">${R$(a.pago.total)}</td></tr>`).join('')}${db.sangrias.map((s) => `<tr><td>Sangria · ${es(s.m)}</td><td></td><td class="d">−${R$(s.v)}</td></tr>`).join('')}</tbody></table></section>${lista('fechamentos').length ? `<section class="caixa-b c12"><h2>Fechamentos</h2><table><thead><tr><th>Quando</th><th class="d">Sistema</th><th class="d">Contado</th><th class="d">Diferença</th><th>Obs.</th></tr></thead><tbody>${db.fechamentos.slice(-10).reverse().map((f) => `<tr><td>${new Date(f.em).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' })}</td><td class="d">${R$(f.esperado)}</td><td class="d">${R$(f.contado)}</td><td class="d">${f.dif ? `<span class="etq ru">${R$(f.dif)}</span>` : '<span class="etq ok">bateu</span>'}</td><td>${es(f.obs)}</td></tr>`).join('')}</tbody></table></section>` : ''}</div>`;
  },
  lembretes() {
    const am = db.ags.filter((a) => (a.dia || 0) === 1 && a.st === 'agendado').length, l = db.lembretes;
    const am2 = db.ags.filter((a) => (a.dia || 0) === 1 && a.st === 'agendado');
    return `<div class="topo-s"><div><h1>Lembretes</h1><p>O sistema separa quem lembrar e monta a mensagem; o botão abre o seu WhatsApp e quem envia é você. O envio automático depende da API oficial do WhatsApp, que é paga e ainda não está ligada.</p></div><button class="bt az" data-a="novo-lem">+ Lembrete</button></div>
      ${(db.lemManuais || []).length ? `<section class="caixa-b" style="margin-bottom:16px"><h2>Seus lembretes (${db.lemManuais.length})</h2>${db.lemManuais.map((m) => { const c = cli(m.cli); return `<p style="margin:6px 0;display:flex;gap:10px;align-items:center;justify-content:space-between"><span><b>${es(nomeDia(m.dia))}</b> · ${es(c.nome)} · ${es(m.msg)}</span><span style="white-space:nowrap">${c.tel ? `<a class="bt p" target="_blank" rel="noopener" href="https://wa.me/55${String(c.tel).replace(/\D/g, '')}?text=${encodeURIComponent(m.msg)}">Lembrar</a> ` : ''}<button class="bt" data-a="tira-lem" data-id="${m.id}">Feito</button></span></p>`; }).join('')}</section>` : ''}
      ${am2.length ? `<section class="caixa-b" style="margin-bottom:16px"><h2>Confirmar os horários de amanhã (${am2.length})</h2>${am2.map((a) => { const c = cli(a.cli); return `<p style="margin:6px 0;display:flex;gap:10px;align-items:center;justify-content:space-between"><span><b>${hm(a.ini)}</b> · ${es(c.nome)} · ${es(a.itens.filter((i) => i.tipo === 's').map((i) => sv(i.ref).nome).join(' + '))} · ${es(pro(a.pro).nome)}</span>${c.tel ? `<a class="bt p" target="_blank" rel="noopener" href="https://wa.me/55${String(c.tel).replace(/\D/g, '')}?text=${encodeURIComponent(`Oi, ${c.nome.split(' ')[0]}! Confirmando seu horário amanhã às ${hm(a.ini)} com ${pro(a.pro).nome} aqui no ${db.salao}. Responde SIM para confirmar?`)}">Lembrar</a>` : ''}</p>`; }).join('')}</section>` : ''}
      <div class="cols">${[['confirmar', 'Confirmação na véspera', `${am} cliente(s) para lembrar amanhã: a lista aparece acima.`], ['aniversario', 'Aniversário', 'Mostra quem faz aniversário no mês em Clientes, para mandar os parabéns.'], ['retorno', 'Hora de voltar', 'A lista de quem sumiu fica em Chamar de volta, com a mensagem pronta.']].map(([k, n, d]) => `<section class="caixa-b c4"><h2>${n}<input type="checkbox" data-lem="${k}" ${l[k] ? 'checked' : ''} style="width:20px;height:20px;accent-color:var(--azul)" aria-label="${n}"></h2><p class="vazio" style="margin:0">${d}</p></section>`).join('')}</div>`;
  },
  relatorios() {
    const pagos = agsHoje().filter((a) => a.pago), fat = pagos.reduce((s, a) => s + a.pago.total, 0), porS = {}; agsHoje().forEach((a) => a.itens.filter((i) => i.tipo === 's').forEach((i) => { porS[sv(i.ref).nome] = (porS[sv(i.ref).nome] || 0) + sv(i.ref).preco; }));
    const top = Object.entries(porS).sort((a, b) => b[1] - a[1]).slice(0, 6), mx = top[0]?.[1] || 1, ocup = db.pros.map((p) => ({ p, o: agsHoje().filter((a) => a.pro === p.id && a.st !== 'faltou').reduce((s, a) => s + minutos(a), 0) / ((FECHA - ABRE) * 60) }));
    return `<div class="topo-s"><div><h1>Relatórios</h1><p>Hoje até agora.</p></div></div>
      <div class="cols"><div class="caixa-b c3"><span class="rot">Faturado</span><p class="num">${R$(fat)}</p></div><div class="caixa-b c3"><span class="rot">Ticket médio</span><p class="num">${R$(fat / (pagos.length || 1))}</p></div><div class="caixa-b c3"><span class="rot">Faltas</span><p class="num">${agsHoje().filter((a) => a.st === 'faltou').length}</p></div><div class="caixa-b c3"><span class="rot">Agendados</span><p class="num">${agsHoje().length}</p></div>
      <section class="caixa-b c6"><h2>Serviços que mais faturam</h2><div class="barras">${top.map(([n, v]) => `<div class="l"><span>${es(n)}</span><span class="t"><i style="width:${v / mx * 100}%"></i></span><b class="d">${R$(v)}</b></div>`).join('')}</div></section>
      <section class="caixa-b c6"><h2>Ocupação da agenda</h2><div class="barras">${ocup.map(({ p, o }) => `<div class="l"><span>${es(p.nome)}</span><span class="t"><i style="width:${Math.min(100, o * 100)}%;--c:${p.cor}"></i></span><b class="d">${Math.round(o * 100)}%</b></div>`).join('')}</div></section></div>`;
  },
  equipe() {
    const pr = db.plano === 'pro' ? 139 : 79;
    return `<div class="topo-s"><div><h1>Equipe</h1><p>Painel do dono: cada profissional vê a própria agenda e a própria comissão.</p></div><button class="bt az" data-a="nova-pro">+ Profissional</button></div>
      <div class="cols"><section class="caixa-b c7 tab"><table><thead><tr><th>Profissional</th><th>Faz</th><th>Vê</th></tr></thead><tbody>${db.pros.map((p) => `<tr><td><b style="color:${p.cor}">●</b> ${es(p.nome)}</td><td>${es(p.area)}</td><td>agenda e comissão dela</td></tr>`).join('')}<tr><td>Recepção</td><td>balcão e caixa</td><td>tudo menos relatórios</td></tr></tbody></table></section>
      <section class="caixa-b c5"><h2>Plano</h2><p>Assinatura · <b>${R$(pr)}/mês</b></p><div class="acoes"><button class="bt ${db.plano === 'basico' ? 'az' : ''}" data-a="plano" data-v="basico">Assinatura · R$ 79/mês</button></div><p class="vazio">Equipe sem limite, histórico de quem fez o quê e até 10 empresas. Anual com 20% a menos. Sem fidelidade.</p></section></div>`;
  },
  ajustes() {
    return `<div class="topo-s"><div><h1>Ajustes</h1></div></div><div class="cols"><section class="caixa-b c6"><label class="cmp">Nome do salão<input data-aj="salao" value="${es(db.salao)}"></label><label class="cmp">Abertura do caixa (R$)<input data-aj="caixaIni" inputmode="decimal" value="${db.caixaIni}"></label></section>
      <section class="caixa-b c6"><h2>Serviços <button class="bt p az" data-a="novo-serv">+ Serviço</button></h2><table><thead><tr><th>Serviço</th><th class="d">Minutos</th><th class="d">Preço (R$)</th></tr></thead><tbody>${db.servs.map((s) => `<tr><td>${es(s.nome)}</td><td class="d"><input data-serv="${s.id}|min" type="number" min="10" max="480" step="5" value="${s.min}" style="width:70px;text-align:right" aria-label="Minutos de ${es(s.nome)}"></td><td class="d"><input data-serv="${s.id}|preco" inputmode="decimal" value="${String(s.preco).replace('.', ',')}" style="width:80px;text-align:right" aria-label="Preço de ${es(s.nome)}"></td></tr>`).join('')}</tbody></table><p class="vazio">O preço novo vale para os próximos atendimentos; o que já foi pago não muda. Agendamento online com sinal, confirmação automática pelo WhatsApp e NFS-e ainda não estão ligados.</p></section></div>`;
  },
};

function comanda() {
  const a = sel && ag(sel);
  if (!a) {
    const vem = agsHoje().filter((x) => !x.pago && ['agendado', 'chegou', 'atendendo', 'pagar'].includes(x.st)).sort((x, y) => x.ini - y.ini).slice(0, 4);
    return `<section class="caixa-b comanda vazia"><h2>Comanda</h2><p class="vazio">Toque num cliente para abrir a comanda dele.</p>${vem.length ? `<small class="rot">A seguir</small>${vem.map((x) => `<button type="button" class="cartela" data-sel="${x.id}" style="--c:${pro(x.pro).cor}"><b>${hm(x.ini)} ${es(cli(x.cli).nome)}</b><small>${es(x.itens.filter((i) => i.tipo === 's').map((i) => sv(i.ref).nome).join(' + '))} · ${es(pro(x.pro).nome)}</small></button>`).join('')}` : '<p class="vazio">Ninguém marcado para o resto do dia.</p>'}</section>`;
  }
  const c = cli(a.cli), pac = db.pacotes.find((p) => p.cli === a.cli && p.usadas < p.total), prox = { agendado: ['Chegou', 'chegou'], chegou: ['Sentar na cadeira', 'atendendo'], atendendo: ['Terminou: ir pagar', 'pagar'] }[a.st];
  return `<section class="caixa-b comanda"><h2>${es(c.nome)} <span class="etq ${ST[a.st][1]}">${ST[a.st][0]}</span></h2>${c.alerta ? `<p class="alerta-f">Atenção: ${es(c.alerta)}</p>` : ''}${c.obs ? `<p class="vazio" style="margin:-4px 0 8px">Ficha: ${es(c.obs)}</p>` : ''}${faltas(a.cli) ? `<p class="vazio" style="margin:-4px 0 8px;color:#a5533f">Faltou ${faltas(a.cli)} vez(es) sem avisar.</p>` : ''}
    ${a.itens.map((i, ix) => `<div class="linha-c"><span>${es(i.tipo === 's' ? sv(i.ref).nome : prod(i.ref).nome)}<small>${es(pro(i.pro)?.nome || '')}${i.pacote ? ' · do pacote' : ''}${i.tipo === 'p' ? ' · produto' : ''}</small></span><span class="m">${R$(valorItem(i))}</span>${a.st === 'pago' ? '<span></span>' : `<button type="button" class="x" data-tira="${ix}" aria-label="Tirar item">×</button>`}</div>`).join('')}
    <div class="tot"><span>Total</span><span>${R$(a.pago ? a.pago.total : totalAg(a))}</span></div>${a.sinal && !a.pago ? `<p class="vazio">Sinal já pago: ${R$(a.sinal.v)} no ${es(a.sinal.forma)}. Desconta no receber.</p>` : ''}${!a.pago && descPromo(a) ? `<p class="vazio">Promoção de ${DOW[dow(a.dia || 0)]}: ${R$(descPromo(a))} de desconto no receber.</p>` : ''}
    ${a.st === 'pago' ? `<p class="vazio">Pago no ${es(a.pago.forma)}.${a.nota != null ? ` Nota do atendimento: ${a.nota}.` : ''}</p><div class="acoes"><button class="bt p" data-a="recibo">Recibo</button>${a.nota == null ? '<button class="bt p" data-a="avaliar">Avaliação da cliente</button>' : ''}</div>` : a.st === 'faltou' ? '<p class="vazio">Não veio.</p>' : `<div class="acoes"><button class="bt p" data-a="add-serv">+ Serviço</button><button class="bt p" data-a="add-prod">+ Produto</button>${pac && a.itens.some((i) => i.tipo === 's' && !i.pacote) ? `<button class="bt p" data-a="usar-pacote">Usar pacote (${pac.total - pac.usadas})</button>` : ''}</div>
    <div class="acoes" style="margin-top:10px">${prox ? `<button class="bt az" data-a="avanca" data-v="${prox[1]}">${prox[0]}</button>` : ''}${['pagar', 'atendendo', 'chegou'].includes(a.st) ? '<button class="bt ar" data-a="receber">Receber</button>' : ''}${a.st === 'agendado' ? '<button class="bt" data-a="avanca" data-v="faltou">Faltou</button>' : ''}${['agendado', 'chegou'].includes(a.st) ? '<button class="bt" data-a="reagendar">Reagendar</button>' : ''}${['agendado', 'chegou'].includes(a.st) && !a.sinal ? '<button class="bt" data-a="sinal">Sinal</button>' : ''}${a.st === 'agendado' ? '<button class="bt" data-a="desmarcar">Desmarcar</button>' : ''}</div>`}</section>`;
}

function tela() {
  const r = location.hash.slice(1) || 'balcao', n = { balcao: agsHoje().filter((a) => ['chegou', 'pagar'].includes(a.st)).length, produtos: db.prods.filter((p) => p.qtd < p.min).length, online: lista('online').length };
  $('#fichas').innerHTML = SECOES.map(([k, t]) => `<a href="#${k}" ${k === r ? 'aria-current="page"' : ''}>${t}${n[k] ? `<span class="n">${n[k]}</span>` : ''}</a>`).join('');
  $('#miolo').innerHTML = (S[r] || S.balcao)();
  $('#salao').textContent = db.salao; $('#data-hoje').textContent = new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' });
  document.title = `${(SECOES.find(([k]) => k === r) || SECOES[0])[1]} · Veltria Agenda Completo`;
}
addEventListener('hashchange', () => { tela(); $('#miolo').focus({ preventScroll: true }); scrollTo(0, 0); });

function lateral() {
  const g = $('#lateral-ia'); g.hidden = false;
  const fs = db.conversa.length ? db.conversa : [{ ia: 1, t: 'Vejo a agenda, as comandas, os pacotes e o caixa. Na versão contratada, 20 perguntas grátis por dia; aqui as respostas são de exemplo.' }];
  g.innerHTML = `<header><b>Assistente do salão</b><button type="button" data-fecha-l aria-label="Fechar">×</button></header><div class="falas">${fs.map((m) => `<div class="f ${m.ia ? 'ia' : 'eu'}">${es(m.t)}</div>`).join('')}<div class="sug">${['Onde tem buraco hoje?', 'Quem faz aniversário este mês?', 'Que produto está acabando?', 'Escreva a oferta de pacote de escova'].map((s) => `<button type="button" data-sug="${es(s)}">${es(s)}</button>`).join('')}</div></div><form id="f-l"><input id="q-l" placeholder="Pergunte" aria-label="Pergunta"><button class="bt az">Enviar</button></form>`;
  g.querySelector('.falas').scrollTop = 1e6; $('#q-l').focus();
}
function responde(p) {
  const x = sa(p);
  if (/buraco|vago|livre|encaix/.test(x)) return db.pros.map((pr) => { const l = agsHoje().filter((a) => a.pro === pr.id && a.st !== 'faltou').sort((a, b) => a.ini - b.ini); const v = []; let h = ABRE; l.forEach((a) => { if (a.ini - h >= 1) v.push(`${hm(h)}–${hm(a.ini)}`); h = Math.max(h, a.ini + minutos(a) / 60); }); if (FECHA - h >= 1) v.push(`${hm(h)}–${FECHA}:00`); return `• ${pr.nome}: ${v.join(', ') || 'cheia'}`; }).join('\n') + '\n\nPosso mandar os horários para quem está há mais tempo sem vir.';
  if (/aniver/.test(x)) { const m = new Date().getMonth() + 1; const l = db.clientes.filter((c) => Number(c.niver.split('/')[1]) === m); return l.length ? `Este mês: ${l.map((c) => `${c.nome} (${c.niver})`).join(', ')}. O lembrete de aniversário manda os parabéns com 10% de desconto.` : 'Ninguém este mês.'; }
  if (/produto|acaband|estoque/.test(x)) return db.prods.filter((q) => q.qtd < q.min).map((q) => `• ${q.nome}: ${q.qtd} (mínimo ${q.min})`).join('\n') || 'Nada acabando.';
  if (/pacote|oferta|escova/.test(x)) return 'Mensagem pronta:\n\n"Oi! Que tal garantir suas escovas do mês? Pacote com 10 escovas por R$ 450,00 (sai R$ 45 cada, em vez de R$ 55). Vale por 4 meses. Quer que eu separe o seu?"';
  return `Hoje: ${agsHoje().length} atendimentos, ${R$(agsHoje().filter((a) => a.pago).reduce((s, a) => s + a.pago.total, 0))} recebidos.`;
}

